import {setLogger} from '../../shared/logger.js';
import type {Logger} from '../../shared/logger.js';
import {ToolRegistry} from './registry.js';

function createStringFieldRegistry(toolName: string, fieldName: string): {registry: ToolRegistry; wasCalled: () => boolean} {
  const registry = new ToolRegistry();
  let called = false;
  registry.register(
    {
      name: toolName,
      description: `Tool requiring ${fieldName}`,
      inputSchema: {
        type: 'object',
        properties: {[fieldName]: {type: 'string'}},
        required: [fieldName],
      },
    },
    async input => {
      called = true;
      return `ok:${String(input[fieldName])}`;
    }
  );
  return {registry, wasCalled: () => called};
}

function captureAllLogLines(): string[] {
  const lines: string[] = [];
  const sink = (category: string, message: string, data?: Record<string, unknown>) => {
    lines.push(`${category}:${message}:${JSON.stringify(data)}`);
  };
  const logger: Logger = {debug: sink, info: sink, warn: sink, error: sink};
  setLogger(logger);
  return lines;
}

describe('ToolRegistry', () => {
  afterEach(() => {
    setLogger(undefined);
  });

  it('throws at register time naming the tool when a static inputSchema cannot be compiled', () => {
    const registry = new ToolRegistry();
    const invalidDef = {
      name: 'broken_tool',
      description: 'Malformed schema',
      inputSchema: {properties: {count: {type: 'invalid_schema_type'}}},
    };

    expect(() => registry.register(invalidDef, async () => 'unused')).toThrow(/broken_tool/);
  });

  it('rejects input missing a required property with a ToolResponse naming the property and never calls the executor', async () => {
    const {registry, wasCalled} = createStringFieldRegistry('fetch_item', 'itemId');

    const {result} = await registry.execute('fetch_item', {});

    expect([wasCalled(), result.includes('itemId'), /required/i.test(result)]).toEqual([false, true, true]);
  });

  it('passes valid input with an unlisted extra property through to the executor unchanged once', async () => {
    const registry = new ToolRegistry();
    const receivedInputs: Array<Record<string, unknown>> = [];
    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather for a location',
        inputSchema: {
          type: 'object',
          properties: {
            location: {type: 'string'},
            units: {type: 'string', enum: ['celsius', 'fahrenheit'], default: 'celsius'},
          },
          required: ['location'],
        },
      },
      async input => {
        receivedInputs.push(input);
        return '20C';
      }
    );

    const response = await registry.execute('get_weather', {location: 'Berlin', extraKey: 42});

    expect({response, receivedInputs}).toEqual({
      response: {result: '20C'},
      receivedInputs: [{location: 'Berlin', extraKey: 42}],
    });
  });

  it('rejects a wrong-typed property naming the field path and expected type without leaking the value in the result or logs', async () => {
    const logOutput = captureAllLogLines();
    const {registry, wasCalled} = createStringFieldRegistry('lookup_customer', 'secretToken');

    const {result} = await registry.execute('lookup_customer', {secretToken: 987654321});

    expect([
      wasCalled(),
      result.includes('secretToken') && result.includes('string'),
      result.includes('987654321') || logOutput.some(entry => entry.includes('987654321')),
    ]).toEqual([false, true, false]);
  });

  it('throws Unknown tool: <name> when executing an unregistered tool', async () => {
    const registry = new ToolRegistry();

    await expect(registry.execute('missing_tool', {})).rejects.toThrow('Unknown tool: missing_tool');
  });

  it('compiles a static tool schema once at register time across ten execute calls', async () => {
    const registry = new ToolRegistry();
    let schemaReads = 0;
    const schema: Record<string, unknown> = {
      type: 'object',
      properties: {location: {type: 'string'}},
      required: ['location'],
    };
    const definition = {
      name: 'get_weather',
      description: 'Get weather',
      get inputSchema() {
        schemaReads += 1;
        return schema;
